    "defects = [2, 5, 1, 8, 3, 2, 9, 4, 2, 1]\n",
    "\n",
    "# 画出趋势图\n",
    "plt.plot(wafers, defects, marker='o', color='red')\n",
    "plt.title(\"Wafer Defect Trend (Simulation)\")\n",
    "plt.xlabel(\"Wafer ID\")\n",
    "plt.ylabel(\"Defect Count\")\n",
    "plt.show()"
